// frontend/src/utils/SiteImage.jsx
// ✅ v4.2 (Fixed — Stronger Icon Detection + Size Constraint):
//
//  🐛 FIXES نسبت به v3 (اصل):
//  - باگ اصلی: وقتی URL عکس لود می‌شد، looksLikeIconClass نادیده گرفته می‌شد
//    و فقط `max-w-full` اضافه می‌شد. عکس‌های بزرگ آپلودشده با ابعاد طبیعی‌شون
//    رندر می‌شدن و لی‌اوت صفحه (به‌خصوص در پنل ادمین: دکمه‌های فیلتر، نوار
//    جستجو، آیکون‌های جدول) رو دفرم می‌کردن.
//
//  🐛 FIXES نسبت به v4.0/v4.1 (نسخه‌های قبلی fix):
//  - باگ دوم: looksLikeIconClass خیلی محدود بود — فقط classNameهایی رو
//    آیکون تشخیص می‌داد که text- یا w-X h-X (کوچیک) داشتن. این باعث می‌شد
//    مواردی مثل "group-hover:rotate-180 transition-transform duration-500"
//    (آیکون refresh) یا "leading-none inline-flex" (آیکون همه/پول/چارت)
//    به‌عنوان عکس بزرگ تشخیص داده بشن و هنوز دفرم کنن.
//
//  ✅ تغییرات این نسخه (v4.2):
//  ۱. looksLikeIconClass بسیار قوی‌تر شده — حالا لیست کاملی از سیگنال‌های
//     آیکون چک می‌شه: text-X, inline-flex, group-hover:, transition-transform,
//     rotate-, animate-, absolute, leading-none, pointer-events-none, ...
//  ۲. در شاخه‌ی `if (url)`: اگه در icon-mode باشیم، عکس با `width: 1em,
//     height: 1em, objectFit: contain, flexShrink: 0` رندر می‌کنیم.
//  ۳. اگه className صراحتاً size داره (مثل w-6 h-6)، inline style اعمال
//     نمی‌شه تا CSS کار کنه.
//  ۴. برای عکس‌های غیر-icon بدون size explicit: `max-h: 70vh` اضافه می‌شه.
//
//  این فایل فقط یک fix point هست — تمام صفحات ادمین (IngredientsManager،
//  OrdersList، Dashboard، ...) خود‌به‌خود درست می‌شن.
// ============================================================
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_BASE } from '../config/api';

const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

const DEFAULT_IMAGE_SETTINGS = {
  objectFit: 'cover',
  zoom: 100,
  posX: 50,
  posY: 50,
};

const DEFAULT_PLACEHOLDER_CLASS = 'bg-paper-100 dark:bg-ink-700 text-ink-400';

const imageCache = new Map();
const pendingRequests = new Map();

// ============================================================
//  🔄 Version counter — برای force re-render کامپوننت‌ها
// ============================================================
let globalVersion = 0;
const versionListeners = new Set();

function bumpVersion() {
  globalVersion++;
  versionListeners.forEach((listener) => listener(globalVersion));
}

function useCacheVersion() {
  const [version, setVersion] = useState(globalVersion);
  useEffect(() => {
    versionListeners.add(setVersion);
    return () => versionListeners.delete(setVersion);
  }, []);
  return version;
}

// ============================================================
//  📡 BroadcastChannel — cross-tab sync
// ============================================================
const BROADCAST_CHANNEL_NAME = 'miko_site_images_updates';
let broadcastChannel = null;

if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
  try {
    broadcastChannel = new BroadcastChannel(BROADCAST_CHANNEL_NAME);
    broadcastChannel.onmessage = (event) => {
      if (event.data?.type === 'invalidate') {
        const key = event.data.key;
        if (key) imageCache.delete(key);
        else imageCache.clear();
        bumpVersion();
      }
    };
  } catch (err) {
    console.warn('BroadcastChannel init failed:', err);
  }
}

// ============================================================
//  👁️ Visibility/focus — invalidate وقتی کاربر برمی‌گرده
// ============================================================
if (typeof window !== 'undefined') {
  let lastInvalidation = 0;
  const MIN_INTERVAL = 3000;

  const handler = () => {
    if (document.visibilityState !== 'visible') return;
    const now = Date.now();
    if (now - lastInvalidation < MIN_INTERVAL) return;
    lastInvalidation = now;
    imageCache.clear();
    bumpVersion();
  };

  document.addEventListener('visibilitychange', handler);
  window.addEventListener('focus', handler);
}

// ============================================================
//  ⏰ Watchdog — TTL رو واقعاً اجرا کن
// ============================================================
if (typeof window !== 'undefined') {
  setInterval(() => {
    const now = Date.now();
    let changed = false;
    for (const [key, entry] of imageCache.entries()) {
      if (now - entry.timestamp > CACHE_TTL) {
        imageCache.delete(key);
        changed = true;
      }
    }
    if (changed) bumpVersion();
  }, 60000);
}

// ============================================================
//  Cache helpers
// ============================================================
function getFromCache(key) {
  const entry = imageCache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > CACHE_TTL) {
    imageCache.delete(key);
    return null;
  }
  return entry;
}

function setInCache(key, raw) {
  if (!raw || (!raw.url && !raw.fallback)) return;
  const hasUrl = !!raw.url;
  const fullUrl = hasUrl
    ? (raw.url.startsWith('http') ? raw.url : `${API_BASE}${raw.url}`)
    : null;
  imageCache.set(key, {
    data: {
      url: raw.url || '',
      fallback: raw.fallback || '',
      objectFit: raw.object_fit ?? raw.objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit,
      zoom: raw.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
      posX: raw.pos_x ?? raw.posX ?? DEFAULT_IMAGE_SETTINGS.posX,
      posY: raw.pos_y ?? raw.posY ?? DEFAULT_IMAGE_SETTINGS.posY,
    },
    fullUrl,
    timestamp: Date.now(),
  });
}

function invalidateCache(key = null, broadcast = true) {
  if (key === null) imageCache.clear();
  else imageCache.delete(key);
  bumpVersion();

  if (broadcast && broadcastChannel) {
    try {
      broadcastChannel.postMessage({ type: 'invalidate', key });
    } catch {
      /* silent */
    }
  }
}

// ============================================================
//  Fetch
// ============================================================
async function fetchImageData(key) {
  const normalizedKey = (key || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/-/g, '_');

  if (!normalizedKey) return null;

  const cached = getFromCache(normalizedKey);
  if (cached) return cached;

  if (pendingRequests.has(normalizedKey)) return pendingRequests.get(normalizedKey);

  const promise = axios
    .get(`${API_BASE}/api/site-images/${normalizedKey}`)
    .then((res) => {
      const data = res.data;
      if (!data || (!data.url && !data.fallback)) return null;
      setInCache(normalizedKey, data);
      return getFromCache(normalizedKey);
    })
    .catch((err) => {
      if (err.response?.status === 404) return null;
      console.warn(`خطا در گرفتن عکس '${normalizedKey}':`, err);
      return null;
    })
    .finally(() => {
      pendingRequests.delete(normalizedKey);
    });

  pendingRequests.set(normalizedKey, promise);
  return promise;
}

function fetchImage(key) {
  return fetchImageData(key).then((entry) => entry?.fullUrl || null);
}

function isUrlLike(str) {
  if (!str) return false;
  return /^(https?:|\/|data:)/.test(String(str));
}

// ============================================================
//  Hook: useSiteImage
// ============================================================
export function useSiteImage(key) {
  const version = useCacheVersion();
  const [state, setState] = useState({
    url: null,
    fullUrl: null,
    fallback: '',
    ...DEFAULT_IMAGE_SETTINGS,
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (!key) {
      setState({ url: null, fullUrl: null, fallback: '', ...DEFAULT_IMAGE_SETTINGS, loading: false, error: null });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true }));

    fetchImageData(key)
      .then((entry) => {
        if (cancelled) return;
        if (!entry) {
          setState({ url: null, fullUrl: null, fallback: '', ...DEFAULT_IMAGE_SETTINGS, loading: false, error: null });
          return;
        }
        setState({
          url: entry.fullUrl,
          fullUrl: entry.fullUrl,
          fallback: entry.data.fallback || '',
          objectFit: entry.data.objectFit,
          zoom: entry.data.zoom,
          posX: entry.data.posX,
          posY: entry.data.posY,
          loading: false,
          error: null,
        });
      })
      .catch((err) => {
        if (cancelled) return;
        setState({ url: null, fullUrl: null, fallback: '', ...DEFAULT_IMAGE_SETTINGS, loading: false, error: err });
      });

    return () => {
      cancelled = true;
    };
  }, [key, version]);

  return state;
}

// ============================================================
//  Hook: useSiteImages (batch)
// ============================================================
export function useSiteImages(keys) {
  const version = useCacheVersion();
  const [state, setState] = useState({ images: {}, loading: true });

  useEffect(() => {
    if (!keys || !Array.isArray(keys) || keys.length === 0) {
      setState({ images: {}, loading: false });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true }));

    axios
      .get(`${API_BASE}/api/site-images/batch`, {
        params: { keys: keys.join(',') },
      })
      .then((res) => {
        if (cancelled) return;
        const imagesMap = res.data?.images || {};
        const processed = {};
        for (const [k, v] of Object.entries(imagesMap)) {
          if (v?.url) {
            const fullUrl = v.url.startsWith('http') ? v.url : `${API_BASE}${v.url}`;
            processed[k] = {
              url: fullUrl,
              fullUrl,
              objectFit: v.object_fit ?? v.objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit,
              zoom: v.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
              posX: v.pos_x ?? v.posX ?? DEFAULT_IMAGE_SETTINGS.posX,
              posY: v.pos_y ?? v.posY ?? DEFAULT_IMAGE_SETTINGS.posY,
            };
            setInCache(k, v);
          }
        }
        setState({ images: processed, loading: false });
      })
      .catch((err) => {
        if (cancelled) return;
        console.warn('خطا در گرفتن عکس‌ها (batch):', err);
        setState({ images: {}, loading: false });
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [keys?.join(','), version]);

  return state;
}

// ============================================================
//  ✅ FIX v4.2: تشخیص آیکون — بسیار قوی‌تر
//
//  قبلاً فقط اگه className هم w-X و هم h-X (کوچیک) داشت، یا
//  text- داشت، آیکون حساب می‌شد. این باعث می‌شد مواردی مثل:
//    - "group-hover:rotate-180 transition-transform duration-500"
//    - "leading-none inline-flex"
//    - "absolute ... pointer-events-none"
//  به‌عنوان عکس بزرگ تشخیص داده بشن و لی‌اوت رو دفرم کنن.
//
//  حالا لیست کاملی از سیگنال‌های آیکون چک می‌شه:
//    - text-X (color یا size)
//    - inline-flex / inline-block
//    - group-hover: / transition-transform / rotate- / animate-
//    - absolute (overlay icons)
//    - leading-none / leading-tight
//    - pointer-events-none
//
//  سیگنال‌های عکس بزرگ (که آیکون نیست):
//    - w-full / h-full
//    - block (بدون inline-)
//    - object-cover / object-contain (بدون inline-flex)
// ============================================================
function looksLikeIconClass(className) {
  if (!className) return false;

  // 🚫 سیگنال‌های عکس بزرگ — قطعاً آیکون نیست
  if (className.includes('w-full') || className.includes('h-full')) return false;
  if (/\bblock\b/.test(className) && !className.includes('inline-block')) return false;
  // object-cover/contain بدون inline-flex → عکس بزرگ
  if (/object-(cover|contain|fill|none|scale-down)/.test(className) && !className.includes('inline-flex')) {
    if (!className.includes('text-')) return false;
  }

  // pattern: w-<number> و h-<number>
  const wMatch = className.match(/\bw-(\d+)\b/);
  const hMatch = className.match(/\bh-(\d+)\b/);

  // اگه هر دو هستن، فقط اگه کوچیک باشن (<=12 → ~3rem) آیکونه
  if (wMatch && hMatch) {
    const wSize = parseInt(wMatch[1], 10);
    const hSize = parseInt(hMatch[1], 10);
    return wSize <= 12 && hSize <= 12;
  }

  // اگه فقط یکی از w-X یا h-X هستن (اما هر دو نه):
  if (wMatch || hMatch) {
    const size = wMatch ? parseInt(wMatch[1], 10) : parseInt(hMatch[1], 10);
    return size <= 12;
  }

  // ✅ FIX v4.2: سیگنال‌های مثبت آیکون
  const ICON_SIGNALS = [
    'text-',                  // text-X color یا size
    'inline-flex',
    'inline-block',
    'group-hover:',
    'transition-transform',
    'rotate-',                // rotate-180, rotate-45, ...
    'animate-',
    'absolute',               // overlay icons (مثل آیکون داخل input)
    'leading-none',
    'leading-tight',
    'pointer-events-none',
    'self-center',
    'flex-shrink-0',
  ];

  // اگه هیچ سیگنال آیکون نداره، پیش‌فرض: عکس بزرگ (safe)
  // اینطوری hero images بدون class به‌عنوان عکس بزرگ رندر می‌شن
  return ICON_SIGNALS.some((sig) => className.includes(sig));
}

// ============================================================
//  ✅ FIX v3: تشخیص اندازه‌ی صریح
// ============================================================
function hasExplicitSize(className) {
  if (!className) return false;
  return (
    /\bw-(\d+|full|auto|screen|px|1\/\d+)\b/.test(className) ||
    /\bh-(\d+|full|auto|screen|px|1\/\d+)\b/.test(className) ||
    /\bmax-w-/.test(className) ||
    /\bmax-h-/.test(className) ||
    /\baspect-/.test(className)
  );
}

// ============================================================
//  ✅ FIX v4 (NEW): تشخیص نهایی icon-mode
//  اولویت: isIcon prop صریح > looksLikeIconClass از روی className
// ============================================================
function resolveIsIconMode(isIconProp, className) {
  if (isIconProp === true) return true;
  if (isIconProp === false) return false;
  return looksLikeIconClass(className);
}

// ============================================================
//  ✅ FIX v4 (NEW): استایل آیکون
//  در icon-mode، عکس رو هم‌اندازه‌ی font-size فعلی (1em × 1em)
//  رندر می‌کنیم تا لی‌اوت نپره. این مهم‌ترین تغییر این نسخه‌ست.
// ============================================================
function getIconStyle(customStyle = {}) {
  return {
    width: '1em',
    height: '1em',
    objectFit: 'contain',
    flexShrink: 0,
    ...customStyle,
  };
}

// ============================================================
//  کامپوننت SiteImage
// ============================================================
export function SiteImage({
  imageKey,
  fallback = null,
  alt = '',
  className = '',
  style = {},
  loadingClassName = '',
  showPlaceholder = false,
  placeholderContent = null,
  placeholderClassName = DEFAULT_PLACEHOLDER_CLASS,
  isIcon,
  onError = null,
  objectFit: objectFitProp,
  zoom: zoomProp,
  posX: posXProp,
  posY: posYProp,
  useImageSettings = true,
  ...imgProps
}) {
  const { url, loading, fallback: dbFallback, objectFit, zoom, posX, posY } = useSiteImage(imageKey);
  const finalFallback = fallback ?? dbFallback ?? null;

  // ✅ FIX v4: تشخیص نهایی icon-mode — یک‌بار برای همه شاخه‌ها
  const isIconMode = resolveIsIconMode(isIcon, className);

  // ✅ FIX v3: computedStyle فقط برای <img> اعمال می‌شه، نه برای <span> آیکون
  const computedImgStyle = (() => {
    if (!useImageSettings) return { ...style };

    const finalObjectFit = objectFitProp ?? objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit;
    const finalZoom = zoomProp ?? zoom ?? DEFAULT_IMAGE_SETTINGS.zoom;
    const finalPosX = posXProp ?? posX ?? DEFAULT_IMAGE_SETTINGS.posX;
    const finalPosY = posYProp ?? posY ?? DEFAULT_IMAGE_SETTINGS.posY;

    const dynamic = {
      objectFit: finalObjectFit,
      objectPosition: `${finalPosX}% ${finalPosY}%`,
    };

    if (finalZoom !== 100 && finalZoom > 0) {
      dynamic.transform = `scale(${finalZoom / 100})`;
      dynamic.transformOrigin = `${finalPosX}% ${finalPosY}%`;
    }

    return { ...dynamic, ...style };
  })();

  // ============================================================
  //  ✅ حالت loading
  // ============================================================
  if (loading) {
    if (isIconMode) {
      // آیکون: ایموجی fallback با opacity پایین تا layout نپره
      return (
        <span
          className={`${className} inline-flex items-center justify-center opacity-40 ${loadingClassName}`}
          style={style}
          aria-busy="true"
          aria-label="در حال بارگذاری آیکون..."
        >
          {finalFallback ? <span className="leading-none select-none">{finalFallback}</span> : null}
        </span>
      );
    }

    // تصویر — اگه placeholderContent هست، همونو نشون بده
    if (placeholderContent) {
      return (
        <div
          className={`flex items-center justify-center ${placeholderClassName} ${className} ${loadingClassName}`}
          style={style}
          aria-busy="true"
          aria-label={alt || 'در حال بارگذاری عکس...'}
        >
          {placeholderContent}
        </div>
      );
    }

    return (
      <div
        className={`bg-paper-100 dark:bg-ink-700 animate-pulse ${className} ${loadingClassName}`}
        style={style}
        aria-busy="true"
        aria-label="در حال بارگذاری عکس..."
      />
    );
  }

  // ============================================================
  //  ✅ FIX v4: حالت URL موجود — حالت icon-mode به‌طور جداگانه هندل می‌شه
  //  این اصلی‌ترین تغییر این نسخه‌ست. قبلاً icon-mode فقط در loading
  //  اعمال می‌شد، حالا وقتی URL هم لود شد، عکس با width:1em, height:1em
  //  رندر می‌شه تا لی‌اوت نپره.
  //
  //  ✅ FIX v4.1: اگه className صراحتاً size داره (مثل w-6 h-6)،
  //  دیگه width/height inline اعمال نمی‌کنیم تا CSS کار کنه.
  // ============================================================
  if (url) {
    // ✅ حالت آیکون: عکس رو هم‌اندازه‌ی font-size فعلی کن
    if (isIconMode) {
      const hasSizeClass = hasExplicitSize(className);
      const iconStyle = hasSizeClass
        // اگه CSS size داره، فقط objectFit و flexShrink اضافه کن
        ? { objectFit: 'contain', flexShrink: 0, ...computedImgStyle }
        // اگه size نداره، 1em × 1em اعمال کن
        : getIconStyle(computedImgStyle);

      return (
        <img
          src={url}
          alt={alt}
          className={className}
          style={iconStyle}
          loading="lazy"
          onError={(e) => {
            if (finalFallback && isUrlLike(finalFallback)) {
              e.target.src = finalFallback;
            } else {
              e.target.style.display = 'none';
            }
            onError?.(e);
          }}
          {...imgProps}
        />
      );
    }

    // حالت عکس معمولی — با max-w-full و max-h برای جلوگیری از overflow
    const hasSize = hasExplicitSize(className);
    const sizeConstrainedClassName = hasSize
      ? className
      : `${className} max-w-full`.trim();

    const sizeConstrainedStyle = {
      maxWidth: '100%',
      height: 'auto',
      // ✅ FIX v4: max-height عمودی برای جلوگیری از عکس‌های خیلی بلند
      maxHeight: '70vh',
      ...computedImgStyle,
    };

    return (
      <img
        src={url}
        alt={alt}
        className={sizeConstrainedClassName}
        style={sizeConstrainedStyle}
        loading="lazy"
        onError={(e) => {
          if (finalFallback && isUrlLike(finalFallback)) {
            e.target.src = finalFallback;
          } else {
            e.target.style.display = 'none';
          }
          onError?.(e);
        }}
        {...imgProps}
      />
    );
  }

  // ============================================================
  //  ✅ حالت placeholder (no URL, showPlaceholder=true)
  // ============================================================
  if (showPlaceholder) {
    return (
      <div
        className={`flex items-center justify-center ${placeholderClassName} ${className}`}
        style={style}
        aria-label={alt || 'عکس تنظیم نشده'}
      >
        {placeholderContent || <span className="text-2xl opacity-60" aria-hidden="true">🖼️</span>}
      </div>
    );
  }

  // ============================================================
  //  ✅ حالت fallback (no URL, showPlaceholder=false)
  // ============================================================
  if (finalFallback) {
    if (isUrlLike(finalFallback)) {
      // ✅ FIX v4: اگه icon-mode هست، fallback URL رو هم با اندازه‌ی آیکون رندر کن
      if (isIconMode) {
        return (
          <img
            src={finalFallback}
            alt={alt}
            className={className}
            style={getIconStyle(style)}
            loading="lazy"
            {...imgProps}
          />
        );
      }
      const hasSize = hasExplicitSize(className);
      return (
        <img
          src={finalFallback}
          alt={alt}
          className={hasSize ? className : `${className} max-w-full`.trim()}
          style={{
            maxWidth: '100%',
            height: 'auto',
            maxHeight: '70vh',
            ...style,
          }}
          loading="lazy"
          {...imgProps}
        />
      );
    }
    // fallback ایموجی — در icon-mode، با اندازه‌ی font فعلی
    return (
      <div
        className={`flex items-center justify-center ${className}`}
        style={style}
        aria-label={alt || String(finalFallback)}
      >
        <span className="leading-none select-none">{finalFallback}</span>
      </div>
    );
  }

  return null;
}

// ============================================================
//  Helper exports
// ============================================================
export function prefetchSiteImage(key) {
  return fetchImage(key);
}

export function prefetchSiteImages(keys) {
  if (!Array.isArray(keys)) return Promise.resolve();
  return Promise.all(keys.map((k) => fetchImage(k)));
}

export function invalidateSiteImageCache(key = null) {
  invalidateCache(key, true);
}

export default SiteImage;
